from math import comb


def long_exponential(max_length, coefficient):
    # function to calculate product of all numbers from 1 to max_length
    def prod(x):
        ans = 1
        for i in range(1, x + 1):
            ans = (ans * (1 + coefficient * i)) % MOD
        return ans
    return prod(max_length)


def factorial(max_length):
    # function to calculate product of all numbers from 1 to max_length
    def prod(x):
        ans = 1
        for i in range(1, x + 1):
            ans = (ans * i) % MOD
        return ans
    return prod(max_length)


def main():
    N = int(input())
