    expected_values = [0] * (N + 1)
    dp = [0] * (N + 1)

    for i in range(1, N + 1):
        val = A[i]

        # Ensure dp[i-1] always exists
        if i >= 2:
            dp[i] = ((val - 1) * (val - 2) // 2 + dp[i - 1]) % MOD
            expected_values[i] = (val - 1) * expected_values[i - 1] % MOD
        else:
            dp[i] = 0
            expected_values[i] = 0

        # Create the boosting factor to improve the expression's validity
        bounded_count = ((val - 1) // max_length + 1) ** len(range(1, i + 1))
        bounded_count %= MOD
        dp[i] = min(dp[i], bounded_count * dp[i] + expected_values[i]) % MOD
        expected_values[i] = bounded_count + expected_values[i]

    return (sum(dp) % MOD) % MOD


