    def move(current_positions):
        if not current_positions:
            return None

        if all(is_valid_movement(x) for x in current_positions):
            return ' '.join(current_positions)

        last_move = current_positions[-1]
        next_positions = [path1[(path1.index(x) - 1) % len(path1)] for x in current_positions] + \
                         [path2[path2.index(x) - 1] for x in current_positions]
        next_move = next_positions[-1]
        if next_move == last_move:
            return None

        return ' '.join(current_positions + [next_move]) + ' ' + ' '.join([x for x in next_positions if is_valid_movement(x)])

    for positions1 in set(map(''.join, product('NEWSNES', repeat=2))):
        for positions2 in set(map(''.join, product('NEWSNES', repeat=2))):
            if positions1 > positions2:
                continue
            result = move([positions1 + x for x in product('NEWSNES', repeat=2)])
            if result:
                last_positions[result] = positions1
                break

    output = next((pos for pos, items in last_positions.items() if all(items == positions) for positions in product(last_positions.values(), repeat=2)) or ['NO'])
