def dfs(graph: List[List[int]], visited: List[bool], path_order: List[int], order: int):
    if order >= len(path_order):
        return True
    v = None
    for u in range(len(path_order)):
        if not visited[u] and (v is None or path_order[u] < path_order[v]):
            v = u
    if v is not None:
        d = -1  # To track edge direction
        for u in range(len(path_order)):
            if path_order[u] > v and not graph[u][v]:
                d = v
        if d is None:
            return dfs(graph, visited + [True], path_order + [v], 2*order + 1)
        for u in range(len(path_order)):
            if path_order[u] > v and graph[u][v] and u != d:
                graph[u][v] = False
                graph[v][u] = True
                if dfs(graph, visited + [True], path_order, order):
                    return True
                graph[u][v] = True
                graph[v][u] = False
        return False
    return False

