def can_fit(slogan, sequence):
    distinct_chars = set(slogan)
    if len(distinct_chars) < len(sequence):
        return False
    i = start = 0
    while i < len(sequence):
        if sequence[i] == slogan[start]:
            start += 1
        i += 1
    return len(slogan[start:]) >= 2

def longest_cool_slogan_sequence(name):
    n = len(name)
    cool = [0] * n
    max_cool = 0

    for i in range(n):
        for j in range(i, n):
            if can_fit(name[j-i+1], name[i:]):
                cool[j] = max(cool[j], cool[j-i+1] + 1)
                max_cool = max(max_cool, cool[j])

    return max_cool

