from functools import lru_cache

@lru_cache(maxsize=None)
def expected_value(size):
    # Base case 1: One element permutation
    if size == 1:
        return 1

    # Base case 2: Two elements permutation
    if size == 2:
        return (size * (size - 1)) % (10**9 + 7)

    expected = 0
    for j in range(1, size):
        # Possible increments
        if (j + 1) < size and expected_value(j + 1) < expected_value(size):
            expected += j
        else:
            expected += size - j
    return expected * (expected - 1) // 2 % (10**9 + 7)


