        current_dist, current_node = heapq.heappop(queue)
        if current_dist > distances[current_node]:
            continue
        for neighbor in graph[current_node]:
            distance = current_dist + graph[current_node][neighbor]
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(queue, (distance, neighbor))
    return distances

def second_minimum_price(nums):
    min_heap = [(-num, index) for index, num in enumerate(nums)]
    heapq.heapify(min_heap)
    second_min = None
    while min_heap and len(min_heap) > 1:
        num1, _ = heapq.heappop(min_heap)
        if num1 < 0 and not second_min:
            second_min = -num1
        heapq.heappop(min_heap)
        if min_heap and -min_heap[0][0] < second_min:
            second_min = min_heap[0][0]

    return second_min

